const game=new GF.Game({id:'core-awakening',title:'Core Awakening',width:960,height:540,palette:['#00FFFF','#FFA500','#808080','#FFD700'],background:'#0b0e1a'});

let player, enemies, scoreTimer;

function createPlayer() {
  return {
    x: game.W / 2,
    y: game.H / 2,
    size: 20,
    speed: 200,
    color: game.palette[0],
    dodgeCooldown: 0,
    animFrame: 0
  };
}

function createEnemy(x, y) {
  return {
    x, y,
    size: 30,
    color: game.palette[1],
    attackTimer: 2 + Math.random() * 2
  };
}

function resetGame() {
  player = createPlayer();
  enemies = [createEnemy(100, 100), createEnemy(800, 400)];
  scoreTimer = 0;
}

function updatePlayer(dt) {
  const input = game.input;
  if (input.keys['KeyW']) player.y -= player.speed * dt;
  if (input.keys['KeyS']) player.y += player.speed * dt;
  if (input.keys['KeyA']) player.x -= player.speed * dt;
  if (input.keys['KeyD']) player.x += player.speed * dt;
  player.x = GF.math.clamp(player.x, player.size / 2, game.W - player.size / 2);
  player.y = GF.math.clamp(player.y, player.size / 2, game.H - player.size / 2);
  if (player.dodgeCooldown > 0) player.dodgeCooldown -= dt;
  player.animFrame += dt * 10;
}

function updateEnemies(dt) {
  enemies.forEach(enemy => {
    enemy.attackTimer -= dt;
    if (enemy.attackTimer <= 0) {
      game.shake(5, 0.2);
      game.hitStop(0.1);
      enemy.attackTimer = 2 + Math.random() * 2;
    }
  });
}

function checkCollisions() {
  enemies.forEach(enemy => {
    const dist = GF.math.dist(player.x, player.y, enemy.x, enemy.y);
    if (dist < player.size + enemy.size) {
      game.gameOver({ message: 'You were dismantled!' });
    }
  });
}

function updateScore(dt) {
  scoreTimer += dt;
  if (scoreTimer >= 1) {
    game.addScore(1);
    scoreTimer = 0;
  }
}

function drawBackground(ctx) {
  ctx.fillStyle = game.background;
  ctx.fillRect(0, 0, game.W, game.H);
  // Add animated parallax background
  ctx.fillStyle = '#001f3f';
  ctx.fillRect(0, 0, game.W, game.H / 2);
  ctx.fillStyle = '#003366';
  ctx.fillRect(0, game.H / 2, game.W, game.H / 2);
  // Silhouette machinery
  ctx.strokeStyle = '#003366';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, game.H / 2);
  ctx.lineTo(game.W, game.H / 2);
  ctx.stroke();
}

function drawPlayer(ctx) {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(Math.sin(player.animFrame * 0.1) * 0.05);
  ctx.fillStyle = player.color;
  ctx.beginPath();
  ctx.arc(0, 0, player.size, 0, GF.math.TAU);
  ctx.fill();
  // Add player detail
  ctx.strokeStyle = '#FFD700';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.restore();
}

function drawEnemies(ctx) {
  enemies.forEach(enemy => {
    ctx.fillStyle = enemy.color;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.size, 0, GF.math.TAU);
    ctx.fill();
    // Add enemy detail
    ctx.strokeStyle = '#808080';
    ctx.lineWidth = 2;
    ctx.stroke();
  });
}

function drawHUD(ctx) {
  ctx.save();
  // Frame HUD panel
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(10, 10, 200, 80);
  ctx.restore();
  GF.Draw.text(ctx, 'Score: ' + game.score, 20, 30, { size: 24, color: '#FFD700', align: 'left' });
  GF.Draw.text(ctx, 'Controls: WASD to move', 20, 60, { size: 18, color: '#FFFFFF', align: 'left' });
}

game.add('play', {
  init() {
    resetGame();
  },
  reset() {
    resetGame();
  },
  update(dt) {
    updatePlayer(dt);
    updateEnemies(dt);
    checkCollisions();
    updateScore(dt);
  },
  draw(ctx) {
    drawBackground(ctx);
    drawPlayer(ctx);
    drawEnemies(ctx);
    drawHUD(ctx);
  }
});

game.titleScreen({ subtitle: 'Press any key to start', onStart: () => game.go('play') });
